// @ts-check
// Some portions generated by Claude Code
//
// Round-3 server fixes, verified against a real RDF4J Server + Workbench in a real browser:
//  C6   query timeouts are reported as timeouts, before the first row and while rows stream;
//  C8   adding a namespace onto a bound prefix needs overwrite=true;
//  C11  an Add from a URL that cannot be read is an error on the Add page;
//  C13  SHACL validation failures of Update and Add read as one line per violation;
//  C14  repository ids that are not URL-safe are refused with a clear message;
//  C15  the credentials cookie is UTF-8 (user names beyond Latin-1);
//  C25  the delete safety check answers JSON;
//  C32c Summary counts of an unreachable SPARQL endpoint answer the reason instead of a server error.
const net = require('node:net');
const { test, expect } = require('@playwright/test');
const {
    deleteRepository,
    openQueryPage,
    serverBaseUrl,
    setQueryEditor,
    uniqueRepositoryId,
    waitForRoute,
    workbenchBaseUrl
} = require('./workbench-test-helpers');

const SERVER = serverBaseUrl();
const WORKBENCH = workbenchBaseUrl();
const PAGE_DATA = 'application/vnd.rdf4j.workbench+ndjson';

function pageUrl(id, view) {
    return `${WORKBENCH}/repositories/${encodeURIComponent(id)}/${view}`;
}

async function putRepository(request, id, implementation, label = `Round 3 ${id}`) {
    const created = await request.put(`${SERVER}/repositories/${encodeURIComponent(id)}`, {
        headers: { 'Content-Type': 'text/turtle' },
        data: `@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix config: <tag:rdf4j.org,2023:config/> .
[] a config:Repository ; config:rep.id "${id}" ; rdfs:label "${label}" ;
   config:rep.impl ${implementation} .`
    });
    expect([200, 201, 204], `creating ${id}`).toContain(created.status());
}

const MEMORY_STORE = '[ config:rep.type "openrdf:SailRepository" ; '
    + 'config:sail.impl [ config:sail.type "openrdf:MemoryStore" ; config:mem.persist false ] ]';

const SHACL_STORE = '[ config:rep.type "openrdf:SailRepository" ; config:sail.impl [ '
    + 'config:sail.type "rdf4j:ShaclSail" ; config:delegate [ config:sail.type "openrdf:MemoryStore" ] ] ]';

async function post(request, id, contentType, data, context) {
    const query = context ? `?context=${encodeURIComponent('<' + context + '>')}` : '';
    const loaded = await request.post(`${SERVER}/repositories/${encodeURIComponent(id)}/statements${query}`, {
        headers: { 'Content-Type': contentType }, data
    });
    expect([200, 204], `loading into ${id}`).toContain(loaded.status());
}

async function serverNamespace(request, id, prefix) {
    const answer = await request.get(`${SERVER}/repositories/${encodeURIComponent(id)}/namespaces/${prefix}`);
    return answer.status() === 200 ? (await answer.text()).trim() : null;
}

/** The text of the page's outlet, whitespace collapsed. */
async function outletText(page) {
    return (await page.locator('#workbench-outlet').innerText()).replace(/\s+/g, ' ');
}

/** Sends a form from the page like the Workbench router does, asking for the page model; answers status and body. */
async function sendForPageData(page, url, fields, method = 'POST') {
    return page.evaluate(async ([target, form, accept, verb]) => {
        const body = new URLSearchParams(form);
        const response = await fetch(verb === 'GET' ? `${target}?${body}` : target, verb === 'GET'
            ? { headers: { Accept: accept } }
            : { method: verb, headers: { Accept: accept }, body, redirect: 'manual' });
        return { status: response.status, type: response.headers.get('content-type') || '',
            text: response.type === 'opaqueredirect' ? '' : await response.text(),
            redirected: response.type === 'opaqueredirect' };
    }, [url, fields, PAGE_DATA, method]);
}

function records(text) {
    return text.trim().split('\n').filter(Boolean).map(line => JSON.parse(line));
}

function metadataOf(text) {
    return Object.assign({}, ...records(text).filter(record => record.type === 'metadata' || record.type === 'end')
        .map(record => record.values || record.metadata || {}));
}

/** The first row's value of a column of a page model. */
function columnOf(text, name) {
    const all = records(text);
    const vars = all.filter(record => record.type === 'vars').flatMap(record => record.values);
    const rows = all.filter(record => record.type === 'rows').flatMap(record => record.values);
    const index = vars.indexOf(name);
    const cell = index >= 0 && rows.length ? rows[0][index] : null;
    return cell && typeof cell === 'object' ? cell.value : cell;
}

async function closedPort() {
    return new Promise((resolve, reject) => {
        const server = net.createServer();
        server.listen(0, '127.0.0.1', () => {
            const { port } = server.address();
            server.close(() => resolve(port));
        });
        server.on('error', reject);
    });
}

/** Whether a confirmation dialog opens within two seconds (a client may ask before it sends). */
async function dialogShown(dialog) {
    return dialog.waitFor({ state: 'visible', timeout: 2000 }).then(() => true, () => false);
}

async function setQueryTimeout(page, seconds) {
    await page.locator('#query-options-toggle').click();
    await page.locator('#query-timeout').fill(String(seconds));
    await page.keyboard.press('Escape');
}

async function waitForQueryEnd(page) {
    await page.waitForFunction(() => {
        const results = document.querySelector('#query-results');
        const status = results && results.querySelector('.query-result-status');
        return !!results && results.getAttribute('aria-busy') === 'false' && !!status && !!status.textContent
            && !/Receiving|Loading|Running|Waiting/i.test(status.textContent);
    }, null, { timeout: 45000 });
}

test.describe('C6 query timeouts', () => {
    const repositoryId = uniqueRepositoryId('round3-timeout');

    test.beforeAll(async ({ request }) => {
        await putRepository(request, repositoryId, MEMORY_STORE);
        const rows = Array.from({ length: 5000 }, (_unused, index) =>
            `<http://example.org/row${index}> <http://example.org/index> "${index}"^^<http://www.w3.org/2001/XMLSchema#integer> .`);
        await post(request, repositoryId, 'application/n-triples', rows.join('\n'));
    });

    test.afterAll(async ({ request }) => {
        await deleteRepository(request, SERVER, repositoryId);
    });

    test('a query that times out before its first row says that it timed out', async ({ page }) => {
        test.setTimeout(90000);
        await openQueryPage(page, repositoryId);
        await setQueryTimeout(page, 1);
        await setQueryEditor(page, 'PREFIX ex: <http://example.org/>\n'
            + 'SELECT (COUNT(*) AS ?n) WHERE { ?a ex:index ?i . ?b ex:index ?j . ?c ex:index ?k }');
        const answer = page.waitForResponse(response => response.request().method() === 'POST'
            && /\/query(?:[?#]|$)/.test(response.url()));
        await page.locator('#exec').click();
        expect((await answer).status(), 'a timeout is answered 503, not 400').toBe(503);
        await waitForQueryEnd(page);

        const results = (await page.locator('#query-results').innerText()).replace(/\s+/g, ' ');
        expect(results).toContain('Query timed out after 1 second');
        expect(results).not.toMatch(/Read timed out|The query failed/);
    });

    test('a query that times out while its rows stream keeps them and says that it timed out', async ({ page }) => {
        test.setTimeout(90000);
        await openQueryPage(page, repositoryId);
        await setQueryTimeout(page, 2);
        await setQueryEditor(page, 'PREFIX ex: <http://example.org/>\n'
            + 'SELECT ?a ?b WHERE { ?a ex:index ?i . ?b ex:index ?j FILTER(?j > ?i * 2 + 9000 || ?i < 2) }');
        await page.locator('#exec').click();
        await waitForQueryEnd(page);

        const status = (await page.locator('#query-results .query-result-status').first().innerText())
            .replace(/\s+/g, ' ');
        expect(status).toMatch(/rows received before the query timed out/);
        const results = (await page.locator('#query-results').innerText()).replace(/\s+/g, ' ');
        expect(results).toContain('Query timed out after 2 seconds');
        expect(results).not.toMatch(/stream ended|results are incomplete/i);
    });
});

test.describe('C8 adding a namespace onto a bound prefix', () => {
    const repositoryId = uniqueRepositoryId('round3-namespaces');

    test.beforeAll(async ({ request }) => {
        await putRepository(request, repositoryId, MEMORY_STORE);
        const bound = await request.put(`${SERVER}/repositories/${repositoryId}/namespaces/foaf`,
            { headers: { 'Content-Type': 'text/plain' }, data: 'http://xmlns.com/foaf/0.1/' });
        expect([200, 204]).toContain(bound.status());
    });

    test.afterAll(async ({ request }) => {
        await deleteRepository(request, SERVER, repositoryId);
    });

    test('Add namespace with a bound prefix does not silently replace it', async ({ page, request }) => {
        await page.goto(pageUrl(repositoryId, 'namespaces'), { waitUntil: 'domcontentloaded' });
        await waitForRoute(page, 'namespaces');
        await page.getByRole('button', { name: 'Add namespace' }).click();
        const inputs = page.locator('.workbench-namespace-edit input');
        await inputs.nth(0).fill('foaf');
        await inputs.nth(1).fill('http://other.example/');
        const sent = page.waitForResponse(response => response.request().method() === 'POST'
            && /\/namespaces(?:[?#]|$)/.test(response.url()), { timeout: 5000 }).catch(() => null);
        await page.getByRole('button', { name: 'Save' }).click();
        // A client that asks first may show a confirmation: decline it.
        const dialog = page.locator('dialog[open]');
        if (await dialogShown(dialog)) {
            await dialog.getByRole('button', { name: 'Cancel' }).click();
        }
        await sent;
        await expect.poll(() => serverNamespace(request, repositoryId, 'foaf'),
            'the bound prefix keeps its namespace').toBe('http://xmlns.com/foaf/0.1/');
    });

    test('the server refuses the replacement until overwrite=true confirms it', async ({ page, request }) => {
        await page.goto(pageUrl(repositoryId, 'namespaces'), { waitUntil: 'domcontentloaded' });
        await waitForRoute(page, 'namespaces');
        const target = pageUrl(repositoryId, 'namespaces');
        const refused = await sendForPageData(page, target,
            { action: 'save', prefix: 'foaf', namespace: 'http://other.example/' });
        expect(refused.status).toBe(400);
        const metadata = metadataOf(refused.text);
        expect(metadata['error-message']).toBe("Prefix 'foaf' is already defined");
        expect(metadata['existing-namespace']).toBe('http://xmlns.com/foaf/0.1/');
        expect(await serverNamespace(request, repositoryId, 'foaf')).toBe('http://xmlns.com/foaf/0.1/');

        const confirmed = await sendForPageData(page, target,
            { action: 'save', prefix: 'foaf', namespace: 'http://other.example/', overwrite: 'true' });
        expect(confirmed.redirected || confirmed.status === 200, `answered ${confirmed.status}`).toBe(true);
        expect(await serverNamespace(request, repositoryId, 'foaf')).toBe('http://other.example/');
    });
});

test.describe('C11 Add from a URL that cannot be read', () => {
    const repositoryId = uniqueRepositoryId('round3-add-url');

    test.beforeAll(async ({ request }) => {
        await putRepository(request, repositoryId, MEMORY_STORE);
    });

    test.afterAll(async ({ request }) => {
        await deleteRepository(request, SERVER, repositoryId);
    });

    async function addFromUrl(page, url) {
        await page.goto(pageUrl(repositoryId, 'add'), { waitUntil: 'domcontentloaded' });
        await waitForRoute(page, 'add');
        await page.locator('label[for="source-url"]').click();
        await page.locator('#url').fill(url);
        const answer = page.waitForResponse(response => response.request().method() === 'POST'
            && /\/add(?:[?#]|$)/.test(response.url()));
        await page.locator('#workbench-outlet [type=submit]').first().click();
        return answer;
    }

    test('a URL that answers 404 is reported on the Add page', async ({ page }) => {
        const url = `${SERVER}/round3-does-not-exist.ttl`;
        const answer = await addFromUrl(page, url);
        expect(answer.status(), 'not a server error').toBeLessThan(500);
        await expect(page.locator('#workbench-outlet')).toContainText(`Could not read ${url}: 404 Not Found`);
        await expect(page.locator('#workbench-outlet')).not.toContainText('The server answered 500');
    });

    test('a URL whose server refuses the connection is reported on the Add page', async ({ page }) => {
        const url = `http://127.0.0.1:${await closedPort()}/data.ttl`;
        const answer = await addFromUrl(page, url);
        expect(answer.status(), 'not a server error').toBeLessThan(500);
        await expect(page.locator('#workbench-outlet')).toContainText(`Could not read ${url}: Connection refused`);
    });
});

test.describe('C13 SHACL validation failures', () => {
    const repositoryId = uniqueRepositoryId('round3-shacl');

    test.beforeAll(async ({ request }) => {
        await putRepository(request, repositoryId, SHACL_STORE);
        await post(request, repositoryId, 'text/turtle', `@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix ex: <http://example.org/> .
ex:PersonShape a sh:NodeShape ; sh:targetClass ex:Person ;
  sh:property [ sh:path ex:age ; sh:datatype <http://www.w3.org/2001/XMLSchema#integer> ; sh:maxCount 1 ] .`,
            'http://rdf4j.org/schema/rdf4j#SHACLShapeGraph');
        const bound = await request.put(`${SERVER}/repositories/${repositoryId}/namespaces/ex`,
            { headers: { 'Content-Type': 'text/plain' }, data: 'http://example.org/' });
        expect([200, 204]).toContain(bound.status());
    });

    test.afterAll(async ({ request }) => {
        await deleteRepository(request, SERVER, repositoryId);
    });

    test('an Update that violates a shape lists the violations', async ({ page }) => {
        await page.goto(pageUrl(repositoryId, 'update'), { waitUntil: 'domcontentloaded' });
        await waitForRoute(page, 'update');
        await page.locator('#workbench-outlet .CodeMirror').first().evaluate((element, value) => {
            element.CodeMirror.setValue(value);
        }, 'PREFIX ex: <http://example.org/>\nINSERT DATA { ex:p1 a ex:Person ; ex:age "old" , "older" . }');
        await page.locator('#workbench-outlet [type=submit]').first().click();

        await expect(page.locator('#workbench-outlet')).toContainText('SHACL validation failed with 3 violations',
            { timeout: 15000 });
        const text = await outletText(page);
        expect(text).toContain('- ex:p1, ex:age: expected at most 1 value');
        expect(text).toContain('- ex:p1, ex:age: value "old": expected datatype xsd:integer');
        expect(text).not.toContain('RemoteShaclValidationException');
    });

    test('an Add that violates a shape lists the violations', async ({ page }) => {
        await page.goto(pageUrl(repositoryId, 'add'), { waitUntil: 'domcontentloaded' });
        await waitForRoute(page, 'add');
        await page.locator('label[for="source-text"]').click();
        await page.locator('#text').fill('@prefix ex: <http://example.org/> .\nex:p2 a ex:Person ; ex:age "x" .');
        const answer = page.waitForResponse(response => response.request().method() === 'POST'
            && /\/add(?:[?#]|$)/.test(response.url()));
        await page.locator('#workbench-outlet [type=submit]').first().click();
        const body = await (await answer).text();

        const error = records(body).find(record => record.type === 'error');
        expect(error && error.code).toBe('shacl-validation');
        expect(error.message).toBe('SHACL validation failed with 1 violation:\n'
            + '- ex:p2, ex:age: value "x": expected datatype xsd:integer');
        await expect(page.locator('#workbench-outlet'))
            .toContainText('SHACL validation failed with 1 violation', { timeout: 15000 });
        expect(await outletText(page)).not.toMatch(/@prefix|sh:ValidationReport/);
    });
});

test.describe('C14 repository ids that are not URL-safe', () => {
    test('the server refuses them with a clear message, and Create shows no URL error', async ({ page, request }) => {
        await page.goto(`${WORKBENCH}/repositories/NONE/create`, { waitUntil: 'domcontentloaded' });
        await waitForRoute(page, 'create');
        const refused = await sendForPageData(page, `${WORKBENCH}/repositories/NONE/create`,
            { type: 'memory', 'Repository ID': 'bad id', 'Repository title': 'Round 3' });
        expect(refused.status).toBe(400);
        expect(columnOf(refused.text, 'error-message')).toBe("Repository ID 'bad id' is not valid: use only "
            + "the letters a-z and A-Z, digits, '-', '_', '.' and '@', and not only dots.");

        await page.locator('#type').selectOption('memory');
        await page.locator('#workbench-outlet [type=submit]').click();
        await page.locator('#create').waitFor({ state: 'visible', timeout: 15000 });
        await page.locator('#config_rep-id').fill('bad id');
        // The client explains such an id as it is typed and keeps Create disabled; a client that still offers it
        // may ask first: accept, the server decides.
        if (await page.locator('#create').isEnabled()) {
            await page.locator('#create').click();
            const dialog = page.locator('dialog[open]');
            if (await dialogShown(dialog)) {
                await dialog.locator('button').filter({ hasNotText: 'Cancel' }).last().click();
            }
        }
        await expect(page.locator('#workbench-outlet')).toContainText(/not valid|only.*letters/i, { timeout: 15000 });
        expect(await outletText(page)).not.toContain('Illegal character');
        const listed = await request.get(`${SERVER}/repositories/bad%20id/size`);
        expect(listed.status(), 'no repository was created').toBe(404);
    });
});

test.describe('C15 credentials beyond Latin-1', () => {
    const repositoryId = uniqueRepositoryId('round3-credentials');
    const queryName = `utf8-${Date.now().toString(36)}`;

    test.beforeAll(async ({ request }) => {
        await putRepository(request, repositoryId, MEMORY_STORE);
    });

    test.afterAll(async ({ request }) => {
        await deleteRepository(request, SERVER, repositoryId);
    });

    test('a private query saved by a user named beyond Latin-1 belongs to that user', async ({ page, context }) => {
        const host = new URL(WORKBENCH);
        await context.addCookies([{
            name: 'server-user-password',
            value: Buffer.from('håvard✓:pass✓', 'utf8').toString('base64'),
            domain: host.hostname,
            path: '/'
        }]);
        const saved = await page.request.post(pageUrl(repositoryId, 'query'), {
            form: { action: 'save', 'query-name': queryName, queryLn: 'SPARQL',
                query: 'SELECT * WHERE { ?s ?p ?o } LIMIT 1', 'save-private': 'true', 'query-timeout': '0' }
        });
        expect(saved.status()).toBe(200);

        await page.goto(pageUrl(repositoryId, 'saved-queries'), { waitUntil: 'domcontentloaded' });
        await waitForRoute(page, 'saved-queries');
        const row = page.locator('.saved-query-row').filter({ hasText: queryName });
        await expect(row).toHaveCount(1);
        await expect(row.locator('.saved-query-row__heading')).toContainText('håvard✓');
    });
});

test.describe('C25 delete safety check', () => {
    const repositoryId = uniqueRepositoryId('round3-delete');

    test.beforeAll(async ({ request }) => {
        await putRepository(request, repositoryId, MEMORY_STORE);
    });

    test.afterAll(async ({ request }) => {
        await deleteRepository(request, SERVER, repositoryId);
    });

    test('the safety check answers JSON and the browser reads it without an XML parsing error', async ({ page }) => {
        const messages = [];
        page.on('console', message => messages.push(message.text()));
        await page.goto(`${WORKBENCH}/repositories/NONE/delete`, { waitUntil: 'domcontentloaded' });
        await waitForRoute(page, 'delete');
        const check = await sendForPageData(page, `${WORKBENCH}/repositories/NONE/delete`,
            { checkSafe: repositoryId }, 'GET');
        expect(check.status).toBe(200);
        expect(check.type).toMatch(/^application\/json/);
        expect(JSON.parse(check.text)).toEqual({ safe: true });

        await page.locator('#id').selectOption(repositoryId);
        const answered = page.waitForResponse(response => /checkSafe=/.test(response.url()));
        await page.locator('#workbench-outlet [type=submit], #workbench-outlet button.workbench-action--danger')
            .first().click();
        await answered;
        const dialog = page.locator('dialog[open]');
        await expect(dialog).toBeVisible();
        await dialog.getByRole('button', { name: 'Cancel' }).click();
        expect(messages.filter(text => /XML Parsing Error/i.test(text))).toEqual([]);
    });
});

test.describe('C32c Summary of an unreachable SPARQL endpoint', () => {
    const repositoryId = uniqueRepositoryId('round3-unreachable');

    test.beforeAll(async ({ request }) => {
        await putRepository(request, repositoryId, '[ config:rep.type "openrdf:SPARQLRepository" ; '
            + `config:sparql.queryEndpoint <http://127.0.0.1:${await closedPort()}/sparql> ]`);
    });

    test.afterAll(async ({ request }) => {
        await deleteRepository(request, SERVER, repositoryId);
    });

    test('the counts answer says why there are no counts', async ({ page }) => {
        const counts = page.waitForResponse(response => /[?&]counts=true/.test(response.url()), { timeout: 20000 });
        await page.goto(pageUrl(repositoryId, 'summary'), { waitUntil: 'domcontentloaded' });
        await waitForRoute(page, 'summary');
        const answer = await counts;
        expect(answer.status(), 'not a server error').toBe(200);
        const body = await answer.text();
        expect(metadataOf(body)['counts-failed']).toMatch(/Connect|refused|failed/i);
        expect(columnOf(body, 'size')).toBeFalsy();
    });
});
